{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A close piperazine amide analogue showed brain-to-serum Cmax ratios exceeding 1 in mice after both i.p. and p.o. dosing, directly demonstrating meaningful CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "JJC 4-077, an arylpiperazine amide with a dichlorophenyl piperazine, entered the brain quickly and showed high brain penetration after intravenous administration, supporting CNS access for the query's piperazine amide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "AH-7921, a structurally related amide with a basic amine, had a rat brain-to-plasma ratio of 16.6 and was classified as having good brain penetrability, indicating that this amide/amine class readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "S1RA, a systemically administered CNS ligand with a piperazine/heteroaryl scaffold, crossed the BBB and bound CNS sigma receptors in mice, confirming functional brain exposure for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A piperazine bis-amide analogue was detected at high levels in mouse brain and spinal cord after systemic administration, showing that even more polar piperazine amides can achieve robust CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an arylpiperazine ethylamide with a 4-chlorophenyl piperazine, closely matching multiple analogues with direct evidence of high brain penetration, brain-to-plasma ratios >1, and functional CNS exposure; therefore predicted pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "No explicit P-gp/BCRP efflux data for the query",
    "Most evidence is from rodent or monkey studies rather than human data"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

